#' Turns a delay PMF into a random number generator
#'
#' This function is used to create a random number generator from a distcrete
#' object, a function, or a set of numbers taken to be the PMF on
#' `0:(length(x) - 1)`. It internally uses `[make_pmf_delay()]` to turn its 
#' input into a PMF, then samples delays from this PMF.
#' 
#' @inheritParams make_pmf_delay x
#' 
#' @param max_delay the maximum delay which can be generated by the random
#'   number generator
#' 
#' @author Thibaut Jombart
#' 
#' @export
#' 
#' @examples
#' # RNG from a poisson distribution
#' r_delay <- make_rng_delay(function(x) dpois(x, 2.5))
#' r_delay(10)
#' summary(r_delay(1e4))
#' 
#' # RNG from an empirical weight distribution
#' r_delay <- make_rng_delay(c(0, 1, 1, 2, 4, 2, 1, 1, 0.5, 0.2))
#' r_delay(10)
#' summary(r_delay(1e4))
#' barplot(table(r_delay(1000)))

make_rng_delay <- function(x, max_delay = 1000) {
  
  ## some input checks ; x is checked in make_pmf_delay()
  if (length(max_delay) != 1L) {
    stop("'max_delay' must be a single number")
  }
  
  if (!is.finite(max_delay)) {
    stop("'max_delay' must be a finite number")
  }
  
  if (max_delay < 1) {
    stop("'max_delay' must be >= 1")
  }
  
  ## we extract the PMF and use its probabilities to sample delays from a
  ## multinomial distribution
  pmf <- make_pmf_delay(x)
  delays <- as.integer(seq(0, max_delay, by = 1L))
  probs <- pmf(delays)
  
  function(n = 1) sample(delays, size = n, replace = TRUE, prob = probs)
}
